"""Extend the existing study with proposed motion, asset and interaction briefs."""
import json
from pathlib import Path

r = Path(__file__).resolve().parents[1]
apps = json.loads((r/'data/flows.json').read_text())
sources = {
 'motion-gestures': ('Motion · Gesture animation', 'https://motion.dev/docs/react-gestures', 'Hover, press, focus and drag APIs support feedback on real controls. Specific timings and visual treatments in this study are WDA proposals.'),
 'motion-access': ('Motion · Accessibility', 'https://motion.dev/docs/react-accessibility', 'Reduced-motion policy can govern transforms and custom media behavior. The app must also stop its own shaders and decorative video.'),
 'shader': ('Three.js · ShaderMaterial', 'https://threejs.org/docs/pages/ShaderMaterial.html', 'A custom GLSL material can receive time and resolution uniforms. This supports a proposed procedural light field for Afterglow.'),
 'r3f': ('React Three Fiber · Scaling performance', 'https://r3f.docs.pmnd.rs/advanced/scaling-performance', 'On-demand rendering and explicit invalidation support scenes that stop when still. Reuse geometry and materials; measure the actual mobile workload.'),
 'veo': ('Google · Video generation', 'https://ai.google.dev/gemini-api/docs/video', 'Image-directed video is a motion-study option. Use a currently supported Veo endpoint at production time; these briefs intentionally do not pin a preview model. A generated clip is not editable 3D geometry.'),
 'visibility': ('MDN · Page Visibility API', 'https://developer.mozilla.org/en-US/docs/Web/API/Page_Visibility_API', 'Document visibility changes let the application suspend decorative media when the page is hidden. Resume from state rather than counting background frames.'),
 'pause': ('W3C · Pause, Stop, Hide', 'https://www.w3.org/WAI/WCAG22/Understanding/pause-stop-hide.html', 'Automatically moving content lasting more than five seconds alongside other content needs a way to pause, stop or hide it. This proposal uses short ambient introductions that settle.'),
 'drag-alternative': ('W3C · Dragging movements', 'https://www.w3.org/WAI/WCAG22/Understanding/dragging-movements.html', 'Dragging needs a single-pointer alternative. Petal retains tap-select and tap-target controls as well as keyboard input.')
}
source_records = {k:dict(title=t,url=u,finding=f,checked='2026-10-21',access='read') for k,(t,u,f) in sources.items()}
(r/'research/motion-sources.json').write_text(json.dumps(source_records,indent=2,ensure_ascii=False)+'\n')

