def feedback(c):
 k=c['kind']
 if k in ('status','event'):
  return 'No rollover or press affordance. This is display/state output; never focus it as a button.', 'Update text from real state; announce meaningful changes politely once.'
 if k in ('input','textarea','combobox','time','date','select'):
  return 'Hover: 120 ms border tint. Focus: immediate visible outline with stable label; no scale or placeholder movement. Touch opens the native editing affordance.', 'Freeze decoration during editing. Preserve draft, selection and keyboard position; validate without shaking the field.'
 if k in ('radio','option','switch'):
  return 'Hover: 120 ms outline/tint on the target. Focus-visible stays distinct from selected. Press: 80 ms tint; selection changes only on activation.', 'Selected fill/thumb changes in 140 ms after accepted state; permissions and save failures retain the last valid state. Reduced motion is immediate.'
 if k=='puzzle':
  return 'Hover/focus outlines the active band; no movement until input. Direct horizontal tracking; tap-select/tap-target and keyboard are equivalent routes.', 'Use Petal’s 4% snap threshold and 180 ms settling rule. Cancel restores offset; no automatic progress from animation completion.'
 if k in ('chart','range'):
  return 'Hover/focus previews an exact point/value; tap and keyboard expose the same information. Drag uses direct tracking; no spring on the pointer.', 'Clamp values and update readable labels from one source. Hover never changes saved data or starts playback.'
 if k in ('link','navigation'):
  return 'Hover: 120 ms underline/tint. Focus: immediate outline. Press: 80 ms tint; no image/card movement. Exit restores rest without changing active destination.', 'Route crossfade 160 ms after activation; reduced motion immediate. Active route selection is a no-op; preserve route scroll/drafts.'
 return 'Hover: 120 ms contextual fill/border tint. Focus: immediate visible outline. Press: 80 ms darker tint without layout shift. Exit/canceled press restores rest.', 'Activate on release/keyboard once; preserve labels while pending, suppress duplicate submits, and show explicit success/error. No decorative animation gates the action.'

def write(rel,txt):
 p=r/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(txt.rstrip()+'\n')

for app in apps:
 d=directions[app['id']]
 m={k:v for k,v in d.items() if k!='screens'}
 m['shared']=shared
 m['references']=[source_records[k] for k in d['references']]
 m['path']=f'interaction/motion/{app["id"]}.md'
 m['prompt_path']=f'prompts/interaction/{app["id"]}.txt'
 m['asset_prompt_path']=f'prompts/motion/{app["id"]}-assets.txt'
 m['motion_prompt_path']=f'prompts/motion/{app["id"]}-direction.txt'
 refs='\n'.join(f'- {x["title"]}: {x["url"]}\n  Application: {x["finding"]}' for x in m['references'])
 visual_refs='\n'.join(f'- {s["id"]}: {s["image"]} (approved composition, full screen; do not animate UI pixels)' for s in app['screens'])
